SELECT * FROM (
(SELECT * FROM iot_device_log

   id < #{id}
  AND iot_id = #{iotId}
  AND product_key = #{productKey}
  AND device_id = #{deviceId}
  AND message_type = #{messageType}

    AND event = #{event}
    AND event = #{params.event}


    AND create_time >= #{beginTime,jdbcType=TIMESTAMP}
    AND create_time >= FROM_UNIXTIME(#{params.beginCreateTime})


    AND create_time <= #{endTime,jdbcType=TIMESTAMP}
    AND create_time <= FROM_UNIXTIME(#{params.endCreateTime})


ORDER BY create_time DESC, id DESC LIMIT #{halfSize})

UNION ALL

(SELECT * FROM iot_device_log

  id >= #{id}
  AND iot_id = #{iotId}
  AND product_key = #{productKey}
  AND device_id = #{deviceId}
  AND message_type = #{messageType}

    AND event = #{event}
    AND event = #{params.event}


    AND create_time >= #{beginTime,jdbcType=TIMESTAMP}
    AND create_time >= FROM_UNIXTIME(#{params.beginCreateTime})


    AND create_time <= #{endTime,jdbcType=TIMESTAMP}
    AND create_time <= FROM_UNIXTIME(#{params.endCreateTime})


ORDER BY create_time ASC, id ASC LIMIT #{halfSize})
) AS combined
ORDER BY create_time DESC, id DESC

