select *
from iot_device_log
where iot_id = #{iotId}
  and message_type = #{messageType}
  and create_time >= #{createTime}
  and command_id = #{commandId}
  and command_status = #{commandStatus}
  limit 1


select *
from iot_device_log


    AND iot_id = #{query.iotId}


    AND product_key = #{query.productKey}


    AND device_id = #{query.deviceId}


    AND message_type = #{query.messageType}


    AND id = #{query.logId}


    AND create_time >= FROM_UNIXTIME(#{query.startTime})


    AND create_time <= FROM_UNIXTIME(#{query.endTime})



    AND command_id = #{query.commandId}


    AND command_status = #{query.commandStatus}


    AND event = #{query.eventType}


ORDER BY create_time DESC, id DESC

  LIMIT #{query.limit}

SELECT * FROM iot_device_log
WHERE iot_id = #{iotId} AND product_key = #{productKey}
  AND create_time >= #{beginTime,jdbcType=TIMESTAMP}
  AND create_time <= #{endTime,jdbcType=TIMESTAMP}
  AND device_id = #{deviceId}
  AND message_type = #{messageType}
  AND event = #{event}
  AND id = CAST(#{id} AS SIGNED)

    AND create_time <= #{beforeTime,jdbcType=TIMESTAMP}
    AND (create_time < #{beforeTime,jdbcType=TIMESTAMP}
      OR (create_time = #{beforeTime,jdbcType=TIMESTAMP} AND id < #{beforeId,jdbcType=BIGINT}))

ORDER BY create_time DESC, id DESC LIMIT #{fetchSize}

SELECT COUNT(*) AS totalCount, MAX(create_time) AS latestCreateTime
FROM (
  SELECT create_time FROM iot_device_log
  WHERE iot_id = #{iotId} AND product_key = #{productKey}
    AND message_type = 'EVENT' AND event = #{event}
  ORDER BY create_time DESC LIMIT 100
) recent_events

select.foreach:
SELECT #{eventId,jdbcType=VARCHAR} AS event, COUNT(*) AS totalCount, MAX(create_time) AS latestCreateTime
FROM (
  SELECT create_time FROM iot_device_log
  WHERE iot_id = #{iotId} AND product_key = #{productKey}
    AND message_type = 'EVENT' AND event = #{eventId}
  ORDER BY create_time DESC LIMIT 100
) recent_events
